repl = connect('bash')
# Strip the redundant Write() allow rule the image seeds into
# ~/.claude/settings.json. Newer Claude Code versions warn about it on every
# launch, since file permission checks only match Edit() rules and
# Edit(/home/repl/**) already covers every file-editing tool.
repl.run_command('''python3 - <<'PY'
import json
p = '/home/repl/.claude/settings.json'
try:
    settings = json.load(open(p))
    perms = settings.get('permissions', {})
    perms['allow'] = [r for r in perms.get('allow', []) if not r.startswith('Write(')]
    json.dump(settings, open(p, 'w'), indent=2)
except Exception:
    pass
PY''')
repl.run_command('rm -f /home/repl/queries/.claude/settings.local.json /home/repl/queries/.claude/settings.json')
repl.run_command('mkdir -p /home/repl/queries/hooks')
repl.run_command(r'''cat > /home/repl/queries/hooks/redact-secrets.js <<'EOF'
// PreToolUse hook: keep live API keys out of Bash commands.
// Claude Code sends the tool call to this script as JSON on standard in.
let raw = "";
process.stdin.on("data", (chunk) => (raw += chunk));
process.stdin.on("end", () => {
  const payload = JSON.parse(raw || "{}");
  const input = payload.tool_input || {};
  const command = input.command || "";

  const SECRET = /sk_live_[A-Za-z0-9]+/g;
  if (!command.match(SECRET)) {
    process.exit(0);
  }

  // TODO: rewrite the call so the key is masked and the command still runs.
  process.exit(0);
});
EOF''')
repl.run_command('cd /home/repl/queries && rm -f ~/.claude/history.jsonl'
                 # Transcripts outlive history.jsonl, so a previous exercise's
                 # answers would otherwise be graded as this one's.
                 ' && rm -rf ~/.claude/projects/-home-repl-queries && clear')

