export async function getStalePendingOrders(
  db: Database,
  days: number
): Promise<any[]> {
  const query = `
    SELECT o.order_id, c.first_name, c.last_name, c.phone
    FROM orders o
    JOIN customers c ON c.id = o.customer_id
    WHERE o.status = 'pending'
      AND o.order_date < datetime('now', '-' || ? || ' days')
  `;
  return new Promise((resolve, reject) => {
    db.all(query, [days], (err, rows) => {
      if (err) reject(err);
      else resolve(rows);
    });
  });
